import{_ as t,o,c as a,ah as r}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Research: The Shredder Affair (Reißwolf-Gate)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/schredder-affaere.md","filePath":"en/recherche/schredder-affaere.md"}'),n={name:"en/recherche/schredder-affaere.md"};function i(h,e,s,d,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="research-the-shredder-affair-reißwolf-gate" tabindex="-1">Research: The Shredder Affair (Reißwolf-Gate) <a class="header-anchor" href="#research-the-shredder-affair-reißwolf-gate" aria-label="Permalink to &quot;Research: The Shredder Affair (Reißwolf-Gate)&quot;">​</a></h1><p><strong>When data becomes &quot;unpleasant&quot; – A textbook example of political data hygiene.</strong></p><p>In the context of our mockumentary, we shed light not only on the historical machinations of the Horten era but also on the modern ethics of political transparency. A prime example of handling &quot;unpleasant data&quot; is the Austrian Shredder Affair of 2019.</p><hr><h2 id="the-incident" tabindex="-1">The Incident <a class="header-anchor" href="#the-incident" aria-label="Permalink to &quot;The Incident&quot;">​</a></h2><p>Shortly after the Ibiza video became known, a close confidant of the then-Chancellor Sebastian Kurz, using the pseudonym <strong>&quot;Walter Maisinger&quot;</strong>, brought five hard drives to the company <em>Reisswolf</em>. He had them shredded three times, took the remains back with him, and forgot to pay the bill – which caused the entire action to be exposed.</p><h3 id="key-points" tabindex="-1">Key Points: <a class="header-anchor" href="#key-points" aria-label="Permalink to &quot;Key Points:&quot;">​</a></h3><ul><li><strong>The Timing:</strong> Just days before the change of government and shortly after the &quot;Ibiza&quot; explosion.</li><li><strong>The Procedure:</strong> A conspiratorial action that, according to the ÖVP, only served to &quot;protect sensitive data,&quot; but was interpreted by critics as destruction of evidence.</li><li><strong>The Pseudonym:</strong> The choice of a fake name (&quot;Walter Maisinger&quot;) added a touch of cheap espionage thriller to the affair.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>For the mockumentary, we draw parallels between Helmut Horten&#39;s &quot;market consolidation&quot; and the &quot;data consolidation&quot; of modern politics. Both follow the principle: <em>What is not documented did not happen.</em></p><ul><li><strong>Satirical Motif:</strong> We use the shredder as a symbol for the &quot;Great Forgetting.&quot; Just as the names of the Alsberg brothers were to be erased from the facades, the digital traces of modern networks were to be physically destroyed.</li></ul><hr><p><em>Sources: Reporting by Profil, Standard, and documentation of the investigations by the WKStA.</em></p>',14)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
